-- An application belongs to an event and lists the days the user can go; a match picks one of them. Each existing
-- application keeps its one session as its only day. nearby_main gets access through the default privileges of the
-- database_roles migration.
CREATE TABLE "application_sessions" (
    "application_id" UUID NOT NULL,
    "session_id" UUID NOT NULL,

    CONSTRAINT "application_sessions_pkey" PRIMARY KEY ("application_id", "session_id")
);

CREATE INDEX "application_sessions_session_id_idx" ON "application_sessions"("session_id");

INSERT INTO "application_sessions" ("application_id", "session_id")
SELECT "id", "session_id" FROM "applications";

ALTER TABLE "applications" ADD COLUMN "event_id" UUID;

UPDATE "applications" AS a SET "event_id" = s."event_id" FROM "event_sessions" AS s WHERE s."id" = a."session_id";

ALTER TABLE "applications" ALTER COLUMN "event_id" SET NOT NULL;

-- A user's active applications for days of one event become one: the earliest keeps the days of the others, which
-- are withdrawn.
WITH ranked AS (
    SELECT "id", first_value("id") OVER (PARTITION BY "user_id", "event_id" ORDER BY "created_at", "id") AS "kept"
    FROM "applications"
    WHERE "status" IN ('in_pool', 'paired', 'paused')
)
INSERT INTO "application_sessions" ("application_id", "session_id")
SELECT r."kept", x."session_id"
FROM ranked AS r JOIN "application_sessions" AS x ON x."application_id" = r."id"
WHERE r."id" <> r."kept"
ON CONFLICT DO NOTHING;

WITH ranked AS (
    SELECT "id", first_value("id") OVER (PARTITION BY "user_id", "event_id" ORDER BY "created_at", "id") AS "kept"
    FROM "applications"
    WHERE "status" IN ('in_pool', 'paired', 'paused')
)
UPDATE "applications" SET "status" = 'withdrawn'
WHERE "id" IN (SELECT "id" FROM ranked WHERE "id" <> "kept");

-- One active application per user and event, instead of per session.
DROP INDEX "applications_user_id_session_id_active_key";

CREATE UNIQUE INDEX "applications_user_id_event_id_active_key"
    ON "applications" ("user_id", "event_id")
    WHERE "status" IN ('in_pool', 'paired', 'paused');

ALTER TABLE "applications" DROP CONSTRAINT "applications_session_id_fkey";

ALTER TABLE "applications" DROP COLUMN "session_id";

ALTER TABLE "applications" ADD CONSTRAINT "applications_event_id_fkey"
    FOREIGN KEY ("event_id") REFERENCES "events"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "application_sessions" ADD CONSTRAINT "application_sessions_application_id_fkey"
    FOREIGN KEY ("application_id") REFERENCES "applications"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "application_sessions" ADD CONSTRAINT "application_sessions_session_id_fkey"
    FOREIGN KEY ("session_id") REFERENCES "event_sessions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
